insert into public.clubs (id, slug, name, description, address, meets_at, created_at) values
  ('00000000-0000-4000-b000-000000000001', 'song-han', 'CLB Cờ Vây Sông Hàn', 'Nhóm lâu đời nhất thành phố. Bàn gỗ, trà nóng, và luật bất thành văn: ván nào cũng phải có phút nhận xét sau cuộc.', 'Khu vực cầu Rồng, Hải Châu', 'Thứ bảy · 14:00–18:00', now() - interval '300 days'),
  ('00000000-0000-4000-b000-000000000002', 'tra-that-ky-duyen', 'Trà thất Kỳ Duyên', 'Một căn gác nhỏ có bốn bàn cờ và rất nhiều trà. Hợp cho những ván chậm, ít người, nhiều suy nghĩ.', 'Khu phố cổ Hải Châu', 'Thứ ba & thứ năm · 19:00–22:00', now() - interval '300 days'),
  ('00000000-0000-4000-b000-000000000003', 'son-tra', 'CLB Cờ Vây Sơn Trà', 'Đánh cờ buổi sáng, ăn sáng cùng nhau, rồi đánh tiếp. Có góc dạy người mới.', 'Khu vực Mân Thái, Sơn Trà', 'Chủ nhật · 08:00–11:30', now() - interval '300 days'),
  ('00000000-0000-4000-b000-000000000004', 'sinh-vien', 'Cờ Vây Sinh viên Đà Nẵng', 'Sinh viên các trường đại học cùng chơi, cùng học. Người mới luôn có bàn để ngồi.', 'Khu đại học, Liên Chiểu', 'Thứ tư · 18:30–21:00', now() - interval '300 days'),
  ('00000000-0000-4000-b000-000000000005', 'ngu-hanh-son', 'Nhóm Cờ Vây Ngũ Hành Sơn', 'Nhóm nhỏ, thân, hay hẹn nhau ở quán cà phê gần biển vào tối thứ sáu.', 'Khu vực Mỹ An, Ngũ Hành Sơn', 'Thứ sáu · 19:00–21:30', now() - interval '300 days');
insert into public.users (id, email, display_name, rank_value, club_id, bio, playing_since, created_at) values
  ('00000000-0000-4000-a000-000000000001', 'quang.huy@example.com', 'Lê Quang Huy', 4, '00000000-0000-4000-b000-000000000001', 'Chơi cờ từ thời cấp ba. Thích khai cuộc Trung Quốc và ghét ván hoà.', 2006, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000002', 'cong.son@example.com', 'Đinh Công Sơn', 2, '00000000-0000-4000-b000-000000000005', 'Thầy cờ không chính thức của cả nhóm. Luôn có một nước ''đáng lẽ'' để gợi ý.', 2008, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000003', 'minh.khoi@example.com', 'Trần Minh Khôi', 2, '00000000-0000-4000-b000-000000000001', 'Đánh nhanh, tính chậm. Hay thắng ở trung bàn rồi thua ở yose.', 2011, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000004', 'thu.hien@example.com', 'Nguyễn Thị Thu Hiền', 1, '00000000-0000-4000-b000-000000000003', 'Mỗi sáng chủ nhật đều có mặt. Mê tesuji và bánh mì.', 2014, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000005', 'duc.anh@example.com', 'Phạm Đức Anh', 1, '00000000-0000-4000-b000-000000000002', 'Kiên nhẫn, thủ chắc. Thắng ít khi đậm nhưng hiếm khi thua.', 2013, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000006', 'thanh.tung@example.com', 'Võ Thanh Tùng', 0, '00000000-0000-4000-b000-000000000001', 'Đang cố lên dan trong năm nay. Đã nói vậy ba năm rồi.', 2016, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000007', 'hoai.nam@example.com', 'Đặng Hoài Nam', -1, '00000000-0000-4000-b000-000000000003', 'Thích đánh góc, ngại đánh biên. Luôn mang theo bộ cờ du lịch.', 2017, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000008', 'ngoc.lan@example.com', 'Hồ Ngọc Lan', -1, '00000000-0000-4000-b000-000000000002', 'Học cờ từ bố. Đánh mềm mỏng nhưng cắt rất đau.', 2018, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000009', 'anh.tuan@example.com', 'Bùi Anh Tuấn', -2, '00000000-0000-4000-b000-000000000004', 'Sinh viên năm cuối, kỹ sư tương lai, kỳ thủ hiện tại.', 2019, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000010', 'gia.bao@example.com', 'Trương Gia Bảo', -2, '00000000-0000-4000-b000-000000000004', 'Học cờ qua video, nay muốn thử cờ thật.', 2020, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000011', 'my.linh@example.com', 'Huỳnh Mỹ Linh', -3, '00000000-0000-4000-b000-000000000003', 'Làm thiết kế, đánh cờ như xếp bố cục: thích cân đối.', 2019, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000012', 'quoc.viet@example.com', 'Đỗ Quốc Việt', -3, '00000000-0000-4000-b000-000000000005', 'Đánh đến khuya vẫn tỉnh. Cà phê đen không đường.', 2018, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000013', 'thanh.ha@example.com', 'Lương Thanh Hà', -4, '00000000-0000-4000-b000-000000000002', 'Mới đi cùng bạn, rồi ở lại luôn.', 2021, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000014', 'nhat.nam@example.com', 'Phan Nhật Nam', -5, '00000000-0000-4000-b000-000000000004', 'Chăm chỉ giải bài tsumego trước khi ngủ.', 2022, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000015', 'khanh.vy@example.com', 'Ngô Khánh Vy', -6, '00000000-0000-4000-b000-000000000005', 'Thích bàn 13×13, bảo là ''vừa đủ để suy nghĩ''.', 2022, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000016', 'minh.triet@example.com', 'Châu Minh Triết', -7, '00000000-0000-4000-b000-000000000004', 'Chuyển từ cờ vua sang, vẫn đang quen với việc không có quân bị ăn mất hẳn.', 2023, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000017', 'thao.nguyen@example.com', 'Dương Thảo Nguyên', -7, '00000000-0000-4000-b000-000000000003', 'Học cùng chị Hiền. Đang mê khai cuộc 3-3.', 2023, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000018', 'xuan.thanh@example.com', 'Mai Xuân Thành', -9, '00000000-0000-4000-b000-000000000005', 'Mới học, đang mê. Hỏi gì cũng được, miễn đừng cười.', 2024, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000019', 'tuan.kiet@example.com', 'Lâm Tuấn Kiệt', -11, '00000000-0000-4000-b000-000000000004', 'Ván đầu tiên là ở CLB sinh viên, ván thứ hai là về nhà tự mua bàn cờ.', 2025, now() - interval '260 days'),
  ('00000000-0000-4000-a000-000000000020', 'phuong.thao@example.com', 'Vũ Phương Thảo', -4, '00000000-0000-4000-b000-000000000002', 'Hay đến muộn, hay đi sớm, nhưng ván nào cũng quyết liệt.', 2020, now() - interval '260 days');
